const rockxArea = pl => pl.reduce((v,p,i) => { const q = pl[(i+1)%pl.length]; return v+p[0]*q[1]-q[0]*p[1]; },0);
const rockxAt = (pl,z) => pl.map(([u,v]) => P(u,v,z));
const rockxSq = (k,r) => { const S = 56*k, o = [], m = 8; for (const [cu,cv,a0] of [[S-r,S-r,0],[-S+r,S-r,90],[-S+r,-S+r,180],[S-r,-S+r,270]]) for (let i = 0; i <= m; i++){ const t = (a0+i*90/m)*Math.PI/180; o.push([cu+r*Math.cos(t),cv+r*Math.sin(t)]); } return o; };
const rockxRound = (R,n,cu,cv) => Array.from({length:n},(_,i) => { const t = i/n*2*Math.PI; return [cu+R*Math.cos(t),cv+R*Math.sin(t)]; });
const rockxArc = (cu,cv,r,a0,a1) => Array.from({length:10},(_,i) => { const t = (a0+(a1-a0)*i/9)*Math.PI/180; return [cu+r*Math.cos(t),cv+r*Math.sin(t)]; });
const rockxXtal = (u,v,w,h,a) => [[-w/2+2,-h/2],[w/2-2,-h/2],[w/2,0],[w/2-2,h/2],[-w/2+2,h/2],[-w/2,0]].map(([x,y]) => [u+x*Math.cos(a)-y*Math.sin(a),v+x*Math.sin(a)+y*Math.cos(a)]);
const rockxSlab = (pl,z,h,top,side) => { const T = rockxAt(pl,z+h), B = rockxAt(pl,z), o = rockxArea(pl) > 0 ? 1 : -1, dark = shadeOf(shadeOf(side));
  r0.sol(hull([...T,...B]),dark);
  pl.forEach((p,i) => { const q = pl[(i+1)%pl.length], du = q[0]-p[0], dv = q[1]-p[1], L = Math.hypot(du,dv)||1, nu = o*dv/L, nv = -o*du/L; if (nu+nv <= 0) return; r0.sol([B[i],B[(i+1)%pl.length],T[(i+1)%pl.length],T[i]],mix(side,dark,Math.max(0,Math.min(1,(nv-nu+1)/2)))); });
  rim(hull([...T,...B]),1.1,INK); r0.sol(T,top); return T; };
card({id:'rockx',name:'Exploded view',of:'five igneous rock textures',note:'Each slab is one texture. Touch a slab to read how the rock cooled and which rocks show it.',draw(){
