    {n:'aphanitic',c:['fast, at the surface,','extrusive'],e:'rhyolite, basalt',top:'#b9a9a0',side:'#9d8c82',tex:(Z,T) => { clipped(T,() => { for (let k = 0; k < 70; k++){ const u = -54+(k*37)%108, v = -54+(k*61+k*k*3)%108; r0.sol(rockxAt(rockxRound(.9+(k%3)*.3,8,u,v),Z),k%2 ? '#8e7f78' : '#d6c9bf',.8); } }); }},
