    {n:'vesicular',c:['gas bubbles trapped','in lava'],e:'pumice, scoria',top:'#d9d0c3',side:'#bfb5a5',tex:(Z,T) => { clipped(T,() => { for (const [u,v,r] of [[-30,-24,7],[-8,-34,4],[18,-26,6],[34,-8,4],[-36,2,5],[-12,-8,8],[14,2,5],[30,20,7],[0,22,6],[-26,26,4],[-6,38,4],[20,36,3.5]]){ const q = rockxAt(rockxRound(r,16,u,v),Z); r0.sol(q,'#9a8f80'); r0.sol(rockxAt(rockxRound(r*.65,14,u-r*.15,v-r*.15),Z),'#7b7064'); rim(q,.6,'#7a6f62',.8); } }); }}
  ];
  r0.sol(rockxAt(rockxRound(76,48,0,0),-1).map(([a,b]) => [a+6,b+8]),INK,.12);
  for (let idx = 4; idx >= 0; idx--){ const d = D[idx], z = (4-idx)*gap, ly = 96+idx*62, q = P(s*.98,-s*.2,z+h*.6);
    if (idx > 0) for (const [a,b] of [[s,s],[-s,s],[s,-s]]) dashed(P(a*.94,b*.94,z+h+2),P(a*.94,b*.94,z+gap));
    PT(d.n+': '+d.c.join(' ')+'; '+d.e,() => { const T = rockxSlab(rockxSq(1,10),z,h,d.top,d.side); d.tex(z+h,T); rim(T,1.1,INK);
      TX(300,ly,d.n,{size:17}); d.c.forEach((t,k) => TX(300,ly+16+k*15,t,{size:14,col:LN})); TX(300,ly+16+d.c.length*15,d.e,{size:14}); },{lift:[0,-5]});
    lead([294,ly-5],q,-1);
  }
}});

const zEroR = s => { let t = s; return () => { t = (t*9301+49297)%233280; return t/233280; }; };
const zEroDot = (x,y,r,col,op) => out.push(`<circle cx="${n1(x)}" cy="${n1(y)}" r="${r}" fill="${col}" opacity="${op}"/>`);
const zEroLayer = (x,y,w,h,k,col,seed,ang) => { const R = zEroR(seed), box = [[x,y],[x+w,y],[x+w,y+h],[x,y+h]]; flat(box,col);
  clipped(box,() => {
    if (k < 3) { const n = [70,50,34][k], r = [.7,1,1.6][k]; for (let i = 0; i < n; i++) zEroDot(x+3+R()*(w-6),y+3+R()*(h-6),r,R() < .5 ? mixC(col,TONE,.4) : mixC(col,'#ffffff',.5),.7); }
    else { for (let q = 0; q < 2; q++) for (let c = 0; c < 4; c++) { const cx = x+11+c*19+(q%2)*6+R()*3, cy = y+14+q*23+R()*3, rad = 7+R()*1.5;
      const pts = ang ? Array.from({length:6},(_,i) => { const t = i/6*2*Math.PI+R()*.5, m = rad*(.8+R()*.4); return [cx+m*Math.cos(t),cy+m*Math.sin(t)]; }) : r0.el(cx,cy,rad,rad*.8);
      flat(pts,mixC(col,'#ffffff',.18+R()*.2)); rim(pts,.7,mixC(col,TONE,.5),.9); } }
  });
  lid(box,1.15); };
