const flowRnd = (k) => { const s = Math.sin(k * 127.1 + 311.7) * 43758.5453; return s - Math.floor(s); };
const flowBx = (x, y, w, h) => [[x, y], [x + w, y], [x + w, y + h], [x, y + h]];
const flowPack = (x0, y0, cols, rows, dx, dy, rx, ry, seed, jit, pal) => {
  for (let j = 0; j < rows; j++) for (let i = 0; i < cols; i++) {
    const k = seed + j * 31 + i;
    const cx = x0 + dx * (i + (j % 2 ? .5 : 0)) + (flowRnd(k) - .5) * jit;
    const cy = y0 + dy * j + (flowRnd(k + 7) - .5) * jit;
    const sc = .88 + .24 * flowRnd(k + 3);
    const g = r0.el(cx, cy, rx * sc, ry * sc, 14);
    r0.sol(g, pal[Math.floor(flowRnd(k + 5) * pal.length)]);
    rim(g, .6, '#8f7d5c', .8);
  }
};
const flowPanel = (x, y, bg, fn) => { const pn = rrect(x, y, 136, 96, 6); flat(pn, bg); clipped(pn, fn); lid(pn, 1.2); };
const flowPal = ['#d8c196', '#cdb384', '#e2cfa6', '#c4a97c'];
const flowCap = (x, y, n, name, sub) => {
  TX(x + 68, y + 118, n + '  ' + name, { size: 16, anchor: 'middle' });
  TX(x + 68, y + 136, sub, { size: 14, anchor: 'middle', col: LN });
};

card({id:'flow', name:'Flowchart', of:'sand turning into rock', note:'Follow the arrows: loose sand is buried, squeezed, cemented and becomes rock. Compaction and cementation together are lithification.',
  draw(){
    const T = [[14, 24], [192, 24], [370, 24]], B = [[100, 232], [290, 232]];
    AR([154, 72], [188, 72]);
    AR([332, 72], [366, 72]);
    VHV([438, 172], [168, 228]);
    AR([240, 280], [286, 280]);

    PT('loose sediment: sand grains with open pore space between them', () => {
      const [x, y] = T[0];
      flowPanel(x, y, '#ece4d2', () => { flowPack(x + 6, y + 10, 8, 6, 17, 15, 7, 6, 10, 5, flowPal); });
      flowCap(x, y, '1', 'Loose sediment', 'open pores');
    }, {lift: [0, -5]});

    PT('burial: new layers pile on top of the sand bed', () => {
      const [x, y] = T[1];
      flowPanel(x, y, '#ece4d2', () => {
        flat(flowBx(x, y, 136, 16), '#b3aea2');
        flat(flowBx(x, y + 16, 136, 16), '#c9ae82');
        flat(flowBx(x, y + 32, 136, 14), '#a79c8d');
        rule([[[x, y + 16], [x + 136, y + 16]], [[x, y + 32], [x + 136, y + 32]], [[x, y + 46], [x + 136, y + 46]]], mixC('#a79c8d', TONE, .4), .8, .8);
        flowPack(x + 8, y + 58, 8, 3, 17, 14, 7, 6, 40, 5, flowPal);
      });
      flowCap(x, y, '2', 'Burial', 'layers pile on top');
    }, {lift: [0, -5]});

    PT('compaction: the weight above squeezes the grains together and the pores shrink', () => {
      const [x, y] = T[2];
      flowPanel(x, y, '#bfae8c', () => {
        flat(flowBx(x, y, 136, 26), '#a79c8d');
        rule([[[x, y + 26], [x + 136, y + 26]]], mixC('#a79c8d', TONE, .4), .8, .8);
        flowPack(x + 4, y + 34, 9, 6, 15.5, 11, 8.5, 5.8, 70, 1.5, flowPal);
      });
      AR([438 - 68 + 40, y + 3], [438 - 68 + 40, y + 24]);
      AR([438 - 68 + 96, y + 3], [438 - 68 + 96, y + 24]);
      flowCap(x, y, '3', 'Compaction', 'pores shrink');
    }, {lift: [0, -5]});

    PT('cementation: minerals grow between the grains and fill the pores', () => {
      const [x, y] = B[0];
      flowPanel(x, y, '#dcc080', () => {
        flowPack(x + 4, y + 8, 9, 8, 15.5, 11.5, 8.5, 5.8, 100, 1.5, flowPal);
        for (let k = 0; k < 14; k++) r0.sol(r0.el(x + 8 + flowRnd(k + 200) * 120, y + 8 + flowRnd(k + 300) * 80, 1.6, 1.2, 8), '#efdcae');
      });
      flowCap(x, y, '4', 'Cementation', 'cement fills pores');
    }, {lift: [0, -5]});

    PT('rock: the cemented grains are now solid sandstone', () => {
      const [x, y] = B[1];
      flowPanel(x, y, '#efe9db', () => {
        r0.shadow(x + 72, y + 84, 52, 4, .14);
        const front = [[x + 22, y + 40], [x + 92, y + 40], [x + 92, y + 82], [x + 22, y + 82]];
        const top = [[x + 22, y + 40], [x + 50, y + 22], [x + 120, y + 22], [x + 92, y + 40]];
        const side = [[x + 92, y + 40], [x + 120, y + 22], [x + 120, y + 64], [x + 92, y + 82]];
        flat(front, '#cdb284'); flat(top, '#dcc79c'); flat(side, shadeOf('#cdb284'));
        rule([[[x + 22, y + 52], [x + 92, y + 52]], [[x + 22, y + 63], [x + 92, y + 63]], [[x + 22, y + 73], [x + 92, y + 73]]], mixC('#cdb284', TONE, .35), .7, .8);
        for (let k = 0; k < 30; k++) r0.sol(r0.el(x + 25 + flowRnd(k + 400) * 64, y + 43 + flowRnd(k + 500) * 36, 1.3, 1, 8), flowRnd(k + 600) > .5 ? '#b99d70' : '#e2cfa6');
        lid(front, 1.2); lid(top, 1.2); lid(side, 1.2);
      });
      flowCap(x, y, '5', 'Rock', 'sandstone');
    }, {lift: [0, -5]});
  }});

const zFsBx = (x,y,w,h) => [[x,y],[x+w,y],[x+w,y+h],[x,y+h]];
const zFsBlob = (cx,cy,rx,ry) => spline([[-1,.1],[-.7,-.7],[-.1,-1],[.6,-.8],[1,-.1],[.8,.6],[.1,.85],[-.7,.65]].map(([a,b]) => [cx+a*rx,cy+b*ry]),true,6);
const zFsAng = (x,y,r) => [[0,1],[62,.8],[130,1],[190,.82],[250,.96],[310,.78]].map(([a,k]) => [x+r*k*Math.cos(a*Math.PI/180),y+r*k*Math.sin(a*Math.PI/180)]);
const zFsPiece = (pts,col,w = 1.1) => { flat(pts,col); lid(pts,w); };
const zFsFan = (cx,cy,r) => { const p = [[cx,cy]]; for (let a = 0; a <= 180; a += 15) p.push([cx-r*Math.cos(a*Math.PI/180),cy-r*Math.sin(a*Math.PI/180)]); return p; };
card({id:'zFs',name:'Flowchart',of:'a hand sample examined step by step',note:'Follow the arrows from grain size to the name. Write down what you see at each step before you name the rock.',draw(){
  AR([150,75],[200,75]); AR([320,75],[366,75]); AR([430,174],[430,226]); AR([372,266],[326,266]); AR([204,266],[150,266]);
  PT('1 grain size: measure the grains with a millimeter ruler or a grain-size card',() => {
    const cx = 90, cy = 75, yr = cy+12;
    r0.shadow(cx,yr+23,54,3,.14);
    zFsPiece(zFsBx(cx-52,yr,104,22),'#e6d6a8',1.2);
    rule(Array.from({length:21},(_,i) => [[cx-48+i*4.8,yr],[cx-48+i*4.8,yr+(i%5===0 ? 10 : 5)]]),LN,.7,.9);
    for (const [x,r,c] of [[cx-36,3,'#c9a878'],[cx-14,5.5,'#d4b58a'],[cx+14,9,'#c9a878'],[cx+38,13,'#d9bf94']]) zFsPiece(oval(x,yr-r,r,r),c,1.1);
    TXC(cx,152,'1 Grain size',{size:15});
  },{lift:[0,-5]});
  PT('2 rounding and sorting: are the grains sharp-cornered or rounded, and are they all one size?',() => {
