function stpWave(x,w,y,k){var s=k%2?5:-5;return bend([x-2,y],[x+w/2,y+s],[x+w+2,y-s/2],8);}
card({id:'steps',name:'Step line',of:'rock grade, shale to gneiss',note:'Each step is a rock sample, from shale up to gneiss. Watch the flat layers line up and the grains grow.',draw(){
  const D=[
    {t:'Shale',d:[],c:'#a39a8c',n:'Shale: the bottom step'},
    {t:'Slate',d:['dull,','splits flat'],c:'#6e7378',n:'Slate: dull, splits flat'},
    {t:'Phyllite',d:['silky sheen'],c:'#8f9a94',n:'Phyllite: silky sheen'},
    {t:'Schist',d:['visible mica,','garnet'],c:'#85807a',n:'Schist: visible mica, garnet'},
    {t:'Gneiss',d:['light and dark','bands'],c:'#cfc8bc',n:'Gneiss: light and dark bands'}];
  D.forEach((r,i)=>{
    const x=30+i*88,f=346-i*44,w=88,B=396,face=[[x,f],[x+w,f],[x+w,B],[x,B]];
    PT(r.n,()=>{
      flat([[x+w,f],[x+w+10,f-8],[x+w+10,B-8],[x+w,B]],shadeOf(r.c));
      flat([[x,f],[x+10,f-8],[x+w+10,f-8],[x+w,f]],mixC(r.c,PAPER,.35));
      flat(face,r.c);
      clipped(face,()=>{
        if(i===0){
          for(let y=f+6;y<B-2;y+=6){const j=Math.floor((y-f)/6);rule([[[x+2,y],[x+w-2-(j%3)*14,y]]],mixC(r.c,TONE,.4),.6,.8);if(j%2===0)rule([[[x+4,y+2.5],[x+w-8,y+2.5]]],'#c4bcaf',.5,.7);}
        } else if(i===1){
          for(let y=f+14;y<B;y+=16)rule([[[x,y],[x+w,y]]],mixC(r.c,PAPER,.3),.7,.9);
        } else if(i===2){
          wash([[x,f+16],[x+w,f+10],[x+w,f+26],[x,f+34]],'#dfe6e2');
          wash([[x,f+70],[x+w,f+62],[x+w,f+76],[x,f+86]],'#dfe6e2');
          for(let k=0,y=f+10;y<B;y+=11,k++)r0.ln(bend([x+3,y],[x+w/2,y+(k%2?4:-4)],[x+w-3,y],6),'#d5ddd8',.8,.8);
        } else if(i===3){
          for(let yy=f+12;yy<B-4;yy+=16)for(let xx=x+10+(Math.floor((yy-f)/16)%2)*12;xx<x+w-6;xx+=24)flat([[xx-6,yy+2],[xx+5,yy-2],[xx+6,yy],[xx-5,yy+4]],'#e0dbd0');
          [[x+30,f+30],[x+64,f+70],[x+22,f+104]].forEach(([gx,gy])=>{const g=r0.el(gx,gy,4.5,4.5);flat(g,'#8f3b3b');rim(g,.7,'#5a2424');});
        } else {
          const ys=[f-4];let k=0;const ws=[18,16,24,14,26,18,22,16,24,22,26,20];
          while(ys[ys.length-1]<B+6){ys.push(ys[ys.length-1]+ws[k%ws.length]);k++;}
          for(let b=0;b<ys.length-1;b++){
            const top=stpWave(x,w,ys[b],b),bot=stpWave(x,w,ys[b+1],b+1);
            flat([...top,...bot.slice().reverse()],b%2?'#4d4947':'#e6e0d4');
          }
        }
      });
      lid(face,1.2);
      ink([[x,f],[x+10,f-8],[x+w+10,f-8]],1.2,{over:0});
      ink([[x+w,f],[x+w+10,f-8],[x+w+10,B-8],[x+w,B]],1.2,{over:0});
      TX(x+w/2,r.d.length?f-58:f-24,r.t,{size:16,anchor:'middle'});
      if(r.d.length)TXC(x+w/2,f-(r.d.length===2?34:28),r.d.join('\n'),{size:13.5,col:LN});
    },{lift:[0,-6]});
  });
}});

