const fswimArr = (a,b) => { const g = Math.atan2(b[1]-a[1], b[0]-a[0]); ink([a,b],1.5,{col:LN,over:0}); for (const s of [-1,1]) { const t = g + Math.PI + s*0.5; ink([b,[b[0]+8*Math.cos(t), b[1]+8*Math.sin(t)]],1.5,{col:LN,over:0}); } };
card({id:'faultswim',name:'Swimlane',of:'three fault types by stress and motion',note:'One lane per fault type. Left: the stress. Right: blocks cut at the fault, with red arrows for the motion.',draw(){
  const D = [
    {name:'Normal',stress:'Tension',motion:'Hanging wall moves down',kind:'normal',col:WASH.sky,sn:'Normal fault: tension, the crust is pulled apart'},
    {name:'Reverse',stress:'Compression',motion:'Hanging wall moves up',kind:'reverse',col:WASH.sage,sn:'Reverse fault: compression, the crust is pushed together'},
    {name:'Strike-slip',stress:'Shear',motion:'Blocks slide past horizontally',kind:'strike',col:WASH.rose,sn:'Strike-slip fault: shear, one side is pushed past the other'}];
  const T0 = 44, LH = 112, G = 6, W = 130, H = 54, BX = 323, S = 15;
  TX(24,34,'Fault type',{cap:true,size:14});
  TX(195,34,'Stress',{cap:true,size:14,anchor:'middle'});
  TX(387,34,'Motion',{cap:true,size:14,anchor:'middle'});
  D.forEach((L,i) => {
    const top = T0+i*(LH+G), cy = top+LH/2, by = cy-40;
    const strip = rrect(14,top,492,LH,8); wash(strip,mixC(L.col,PAPER,.5)); lid(strip,1.1);
    rule([[[122,top+8],[122,top+LH-8]],[[268,top+8],[268,top+LH-8]]],LN,.7,.5);
    PT(L.name+' fault',() => TX(24,cy+5,L.name,{size:17}),{lift:[0,-2]});
    PT(L.sn,() => {
      const x0 = 161, x1 = 229, sy = cy-6;
      const r = rrect(x0,sy-13,68,26,3); wash(r,WASH.stone); lid(r,1.1);
      if (L.kind === 'normal') { fswimArr([x0-4,sy],[x0-30,sy]); fswimArr([x1+4,sy],[x1+30,sy]); }
      else if (L.kind === 'reverse') { fswimArr([x0-30,sy],[x0-4,sy]); fswimArr([x1+30,sy],[x1+4,sy]); }
      else { fswimArr([x0+8,sy-17],[x1-8,sy-17]); fswimArr([x1-8,sy+17],[x0+8,sy+17]); }
      TX(195,cy+46,L.stress,{size:15,anchor:'middle'});
    },{lift:[0,-3]});
    if (L.kind === 'strike') {
      const south = [[BX,by+27],[BX+W,by+27],[BX+W,by+H],[BX,by+H]];
      const north = [[BX+16,by],[BX+16+W,by],[BX+16+W,by+27],[BX+16,by+27]];
      PT('Strike-slip fault: the near block slides left',() => { wash(south,WASH.tan); lid(south,1.2); AR([BX+98,by+H+9],[BX+48,by+H+9]); },{lift:[0,-3]});
      PT('Strike-slip fault: the far block slides right',() => { wash(north,WASH.wood); ink([[BX+W,by+27],[BX+W+16,by+27],[BX+W+16,by],[BX+16,by],[BX+16,by+27]],1.2,{over:0}); AR([BX+34,by-9],[BX+84,by-9]); },{lift:[0,-3]});
    } else {
      const k = L.kind === 'normal' ? 1 : -1, sh = [k*S*38/66, k*S*54/66];
      const fxT = BX+48, fxB = BX+86;
      const P1 = [fxT,by], P2 = [BX+W,by], P3 = [BX+W,by+H], P4 = [fxB,by+H];
      const foot = [[BX,by],P1,P4,[BX,by+H]];
      const h = [P1,P2,P3,P4].map(p => [p[0]+sh[0],p[1]+sh[1]]);
      PT(L.name+' fault: the footwall, the block below the fault plane',() => { wash(foot,WASH.tan); lid(foot,1.2); TX(BX+30,by+H/2+5,'footwall',{size:13.5,anchor:'middle'}); },{lift:[0,-3]});
      PT(L.name+' fault: the hanging wall, the block above the fault plane',() => {
        wash(h,WASH.wood);
        ink(L.kind === 'normal' ? [h[0],h[1],h[2],h[3],P4] : [P1,h[0],h[1],h[2],h[3]],1.2,{over:0});
        TXC(BX+98.5+sh[0],by+H/2+sh[1],'hanging\nwall',{size:13.5});
        const a = L.kind === 'normal' ? [BX+W+sh[0]+10,by+4] : [BX+W+sh[0]+28,by+32];
        AR(a,[a[0]+17*k,a[1]+25*k]);
      },{lift:[0,-4]});
    }
    PT(L.name+' fault: '+L.motion,() => TX(387,cy+46,L.motion,{size:14.5,anchor:'middle'}),{lift:[0,-2]});
  });
}});

const orogC = {cont:'#d6c299', oc:'#7f94a6', man:'#d3ab90', sea:'#b8d1e1', sed:'#ece0c2', sky:'#e8eff2', snow:'#f3f5f6'};
const orogPart = (pts,col,w = 1.15) => { flat(pts,col); lid(pts,w); };
const orogDot = (x,y,r,col) => flat(oval(x,y,r,r),col);
const orogMan = (x,y) => orogPart([[x-4,y+56],[x+144,y+56],[x+144,y+124],[x-4,y+124]],orogC.man);
const orogTile = (x,y,fn) => { const fr = rrect(x,y,140,120,6); flat(fr,orogC.sky); clipped(fr,() => fn(x,y)); lid(fr,1.2); };
const orogLab = (x,y,a,b) => { TX(x,y,a,{size:14.5,anchor:'start'}); if (b) TX(x,y+17,b,{size:14.5,anchor:'start'}); };
/* stage 1: an ocean floor slab dives under the far continent */
const orogS1 = (x,y) => {
  const L = x-4, R = x+144;
  orogMan(x,y);
  orogPart([[L,y+50],[x+78,y+50],[x+128,y+122],[x+110,y+122],[x+66,y+58],[L,y+58]],orogC.oc);
  flat([[x+38,y+34],[x+84,y+34],[x+84,y+55],[x+78,y+50],[x+38,y+50]],orogC.sea);
  ink([[x+38,y+34],[x+84,y+34]],.7,{col:LN,over:0});
  orogPart([[L,y+28],[x+38,y+28],[x+38,y+50],[L,y+50]],orogC.cont);
  orogPart([[x+84,y+28],[R,y+28],[R,y+58],[x+84,y+58]],orogC.cont);
};
/* stage 2: the two continents meet, the last ocean floor sinks below */
const orogS2 = (x,y) => {
  const L = x-4, R = x+144;
  orogMan(x,y);
  orogPart([[L,y+56],[x+66,y+56],[x+114,y+122],[x+96,y+122],[x+58,y+64],[L,y+64]],orogC.oc);
  orogPart([[L,y+30],[R,y+30],[R,y+60],[x+70,y+60],[x+70,y+56],[L,y+56]],orogC.cont);
  stem([x+70,y+32],[x+70,y+56],1.6,RED);
};
/* stage 3: folds and thrust slices stack the crust */
const orogS3 = (x,y) => {
  const L = x-4, R = x+144;
  orogMan(x,y);
  const crust = [[L,y+34],[x+34,y+34],[x+52,y+22],[x+70,y+16],[x+88,y+22],[x+106,y+34],[R,y+34],[R,y+58],[x+104,y+58],[x+88,y+72],[x+52,y+72],[x+36,y+58],[L,y+58]];
  orogPart(crust,orogC.cont);
  clipped(crust,() => {
    ink(smooth([[L,y+44],[x+20,y+40],[x+40,y+48],[x+60,y+40],[x+80,y+48],[x+100,y+40],[x+120,y+46],[R,y+42]]),.6,{col:mixC(orogC.cont,TONE,.3),over:0});
    rule([[[x+30,y+76],[x+60,y+22]],[[x+50,y+80],[x+84,y+20]],[[x+74,y+80],[x+104,y+28]]],mixC(orogC.cont,TONE,.6),.9,.9);
  });
};
/* stage 4: the crust is about 70 km thick under the belt */
const orogS4 = (x,y) => {
  const L = x-4, R = x+144;
  orogMan(x,y);
  orogPart([[L,y+34],[x+30,y+34],[x+50,y+16],[x+90,y+16],[x+110,y+34],[R,y+34],[R,y+56],[x+112,y+56],[x+96,y+98],[x+44,y+98],[x+28,y+56],[L,y+56]],orogC.cont);
  rule([[[x+70,y+18],[x+70,y+55]],[[x+70,y+77],[x+70,y+96]],[[x+65,y+18],[x+75,y+18]],[[x+65,y+96],[x+75,y+96]]],INK,.9,.8);
  TXC(x+70,y+66,'70 km',{size:13.5});
};
/* stage 5: high peaks, rock waste washed onto the plain */
const orogS5 = (x,y) => {
  const L = x-4, R = x+144;
  orogMan(x,y);
  orogPart([[L,y+34],[x+26,y+34],[x+42,y+18],[x+52,y+24],[x+68,y+8],[x+80,y+20],[x+90,y+14],[x+110,y+34],[R,y+34],[R,y+56],[x+112,y+56],[x+98,y+92],[x+42,y+92],[x+28,y+56],[L,y+56]],orogC.cont);
  flat([[x+60,y+16],[x+68,y+8],[x+76,y+16],[x+70,y+14],[x+66,y+17]],orogC.snow);
  flat([[x+105,y+29],[x+124,y+28],[R,y+27],[R,y+34],[x+110,y+34]],orogC.sed);
  ink([[x+105,y+29],[x+124,y+28],[R,y+27]],.8,{col:INK,over:0});
  for (const [a,b] of [[x+96,y+22],[x+101,y+27],[x+84,y+22],[x+47,y+26]]) orogDot(a,b,1.3,mixC(orogC.cont,TONE,.4));
};
card({id:'orog',name:'Flowchart',of:'five stages of an orogeny',note:'Read left to right, then down and back along the lower row. Each block is a slice through the crust.',draw(){
  const S = [
