const zCflowBlue = '#a9c3d6';
const zCflowStream = (pts, w) => { const s = smooth(pts); r0.ln(s, '#7f9db4', w + 1.6, .6); r0.ln(s, zCflowBlue, w); r0.ln(s, '#d6e4ee', .7, .8); };
const zCflowTree = (x, y) => { stem([x, y], [x, y + 7], 1, INK); const t = [[x, y - 20], [x + 9, y], [x - 9, y]]; flat(t, '#9fb48a'); lid(t, 1); r0.sol([[x, y - 20], [x + 9, y], [x, y]], shadeOf('#9fb48a'), .4); };
const zCflowPeak = (a, b, c, col) => { r0.part([a, b, c], col, 1.15); r0.sol([b, c, [b[0], c[1]]], shadeOf(col), .45); r0.sol([b, [b[0] - 6, b[1] + 11], [b[0] - 2, b[1] + 8], [b[0] + 2, b[1] + 12], [b[0] + 6, b[1] + 10]], '#f2efe9', .95); };
