const mdrAt = (a,r) => [260 + r*Math.cos(a*Math.PI/180), 220 + r*Math.sin(a*Math.PI/180)];
const mdrLn = (pts,col,w = 1,op = 1,da) => out.push(`<path d='${pathOf(pts)}' fill='none' stroke='${col}' stroke-width='${w}' stroke-linecap='round' stroke-linejoin='round'${op < 1 ? ` opacity='${op}'` : ''}${da ? ` stroke-dasharray='${da}'` : ''}/>`);
const mdrRiver = (pts,w = 6) => { mdrLn(pts,'#7f9db3',w+2); mdrLn(pts,'#a9c6da',w); };
const mdrBank = (pts,c,d) => smooth(pts.map(p => { const dx = p[0]-c[0], dy = p[1]-c[1], l = Math.hypot(dx,dy); return [p[0]+dx/l*d, p[1]+dy/l*d]; }));
const mdrBlob = (cx,cy,rx,ry) => spline(Array.from({length:8},(_,i) => { const t = i/8*2*Math.PI, k = 1+.1*Math.sin(i*2.1); return [cx+rx*k*Math.cos(t), cy+ry*k*Math.sin(t)]; }),true,2);
const mdrSand = (pts) => { flat(pts,'#e4d3a6'); rim(pts,.6,'#bfa974'); };
const mdrFlow = (x,y) => mdrLn([[x-3,y-3],[x+2,y],[x-3,y+3]],'#5f7f96',1);
const mdrTile = (c,fn) => { const t = rrect(c[0]-38,c[1]-27,76,54,4); wash(t,'#d5deb8'); clipped(t,() => { out.push(`<g transform='translate(${n1(c[0])} ${n1(c[1])})'>`); fn(); out.push('</g>'); }); lid(t,1.15); };
card({id:'mdr',sec:'steps',name:'Loop',of:'a river bend from erosion to an oxbow lake',note:'Follow the arrows from 1 to 5: the bend grows, its neck narrows, then a cutoff leaves an oxbow lake. Flow runs left to right.',draw(){
