    () => { mdrLn(smooth(S[1]),'#8fa7b8',1.2,.9,'3 3'); mdrSand(mdrBlob(17,-4,13,9)); mdrRiver(smooth(S[2])); mdrLn(mdrBank([[4,-8],[16,-17],[28,-9]],[16,0],4.4),'#8a6a4c',2); mdrFlow(-27,14); },
