    () => { mdrSand(mdrBlob(1,-8,8,9)); mdrRiver(smooth([[-6,3],[-9,-9],[0,-20],[13,-19],[19,-8],[10,-1],[8,4]])); mdrSand(mdrBlob(-6,8,4,3)); mdrSand(mdrBlob(8,8.5,4,3));
