function stepsCrystal(cx,cy,r,w,col){ for(let k=0;k<6;k++){ const a=k*Math.PI/3, ux=Math.cos(a), uy=Math.sin(a); stem([cx,cy],[cx+ux*r,cy+uy*r],w,col); for(const t of [.5,.78]){ const bx=cx+ux*r*t, by=cy+uy*r*t; for(const s of [-1,1]){ const d=a+s*1.0; stem([bx,by],[bx+Math.cos(d)*r*.28,by+Math.sin(d)*r*.28],w*.75,col); } } } }
