const zBarcoreB = 332, zBarcoreY = k => zBarcoreB - k * 2.6;
const zBarcoreBody = (x, T) => { const p = [[x - 30, T]]; for (let a = 180; a >= 0; a -= 20) { const r = a * Math.PI / 180; p.push([x + 30 * Math.cos(r), zBarcoreB + 7 * Math.sin(r)]); } p.push([x + 30, T]); return p; };
const zBarcoreLayers = (x, T) => { flat([[x - 32, T - 2], [x + 32, T - 2], [x + 32, zBarcoreB + 10], [x - 32, zBarcoreB + 10]], '#c9b48a'); [[40, '#a8906a'], [95, '#b89f78'], [150, '#a8906a'], [205, '#b89f78']].forEach(([d, c]) => { const y = zBarcoreB - d; if (y > T + 4) rule([[[x - 32, y], [x + 32, y]]], c, 3, .7); }); };
card({id:'bar',name:'Bar chart',of:'three orbital cycle lengths in years',note:'Each core is as tall as its cycle is long. The 100,000-year cycle is the tallest, and precession is the shortest.',
  draw(){
