    const B = zBarcoreB, wallC = '#eee6db', cx = i => 120 + i * 120;
    const wall = rrect(20, 18, 480, B - 18, 6); wash(wall, wallC); rim(wall, .9, '#b6b0a4');
    D.forEach(d => { rule([[[66, zBarcoreY(d[1])], [496, zBarcoreY(d[1])]]], '#c0b5a3', .6, .7); });
    TX(28, 46, 'length in years', {size: 14, col: LN});
    /* the bench */
    const top = [[14, B], [506, B], [506, B + 24], [14, B + 24]], front = [[14, B + 24], [506, B + 24], [506, 404], [14, 404]];
    wash(top, '#d6c4a2'); flat(front, '#b4a07c'); rule([[[14, B + 27], [506, B + 27]]], '#cbb893', .8, .8); rim(front, 1.1, INK); lid(top, 1.1);
    /* the cores */
    D.forEach(([n, k, lab, t], i) => { const x = cx(i), T = zBarcoreY(k);
      PT(t, () => {
        flat(oval(x + 12, B + 6, 36, 5), '#b9a888');
        const body = zBarcoreBody(x, T);
        clipped(body, () => zBarcoreLayers(x, T));
        rule([[[x - 21, T + 10], [x - 21, B - 3]]], '#f3ead4', .8, .6);
        ink(body.slice(0, -1), 1.2, {over: 0});
        const tp = oval(x, T, 30, 7); flat(tp, '#e0d2b2'); lid(tp, 1.2);
        const w = textW(lab, 16) + 10; flat(rrect(x - w / 2, T - 33, w, 20, 4), wallC);
        TX(x, T - 17, lab, {anchor: 'middle', size: 16, cls: 'ser', col: k === 100 ? RED : INK});
        const tw = textW(n, 13.5) + 16, tg = rrect(x - tw / 2, B + 34, tw, 26, 4); flat(tg, '#f2e6cb'); rim(tg, .9, INK);
        TX(x, B + 52, n, {anchor: 'middle', size: 13.5, col: INK});
      }, {lift: [0, -5]}); });
  }});
